{"m":1601,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"bilish","d":1,"s":"Maktab pedagogining amaldagi kasbiy standarti nechta asosiy kompetensiya sohasini qamrab oladi?","o":["Besh sohani","Olti sohani","Yetti sohani","To‘qqiz sohani"],"a":2,"e":"Kasbiy standart pedagog faoliyatini o‘quv jarayonini rejalashtirishdan hamkorlikkacha bo‘lgan yetti asosiy kompetensiya sohasida belgilaydi."},
{"m":1602,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"bilish","d":2,"s":"O‘zgaruvchan dunyoda pedagogning yangi talab va majburiyatlarga moslashishga tayyorligini qaysi kompetensiya qo‘llab-quvvatlaydi?","o":["Kasbiy-texnik kompetensiya","Ijtimoiy kompetensiya","Regulyativ kompetensiya","Hissiy kompetensiya"],"a":1,"e":"Ijtimoiy kompetensiya jamiyatdagi o‘zgarishlarni anglash, yangi kasbiy talablar bilan ishlash va turli ishtirokchilar bilan moslashuvchan hamkorlikni ta’minlaydi."},
{"m":1603,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"bilish","d":2,"s":"Quyidagilardan qaysi biri kasbiy standartdagi alohida kompetensiya sohasi nomi emas?","o":["O‘z-o‘zini rivojlantirish va kasbiy o‘sish","Xavfsiz rivojlantiruvchi ta’lim muhitini ta’minlash","Hamkasb va ota-onalar bilan hamkorlik","Pedagogik faoliyatni oqilona tashkil etish"],"a":3,"e":"Dastlabki uch javob standartdagi aniq kompetensiya sohalaridir. Pedagogik faoliyatni oqilona tashkil etish umumiy talab bo‘lib, alohida soha nomi emas."},
{"m":1604,"c":"KS.06","l":"oz-ozini-rivojlantirish-va-kasbiy-osish","k":"bilish","d":1,"s":"Pedagogning shaxsiy-kasbiy sifatlari, bilim, ko‘nikma va malakalariga qo‘yiladigan asosiy talablar jamlanmasi nima?","o":["Pedagogning kasbiy standarti","Pedagogning kasbiy sifati","Pedagogning kasbiy faoliyati","Pedagogning kasbiy burchi"],"a":0,"e":"Kasbiy standart muayyan lavozim yoki kasb uchun zarur mehnat vazifalari, bilim, ko‘nikma, malaka va sifatlar bo‘yicha talablarni belgilaydi."},
{"m":1609,"c":"KS.01","l":"oquv-jarayonini-rejalashtirish","k":"qollash","d":2,"s":"O‘qituvchi baholash natijalariga qarab keyingi dars rejasini o‘zgartirdi. Bu rejalashtirish sohasidagi qaysi ko‘nikma?","o":["Natijani hisobga olib rejani muvofiqlashtirish","Darsda tayyor ko‘rgazmani namoyish etish","O‘quvchi xulqini ma’muriy nazorat qilish","Yakuniy bahoni ota-onaga yetkazish"],"a":0,"e":"Baholashdan olingan dalil asosida maqsad, vazifa yoki usulni moslashtirish o‘quv jarayonini dalillarga tayangan holda rejalashtirish ko‘nikmasidir."},
{"m":1610,"c":"KS.01","l":"oquv-jarayonini-rejalashtirish","k":"bilish","d":2,"s":"O‘quv jarayonini puxta rejalashtirish uchun pedagog qaysi bilimga ega bo‘lishi zarur?","o":["Reja turlari tuzilishi va didaktik tamoyillar","Maktab mulkini inventarizatsiya qilish tartibi","Ota-onalar yig‘ilishini bayonnomalash qoidasi","Faqat yakuniy nazoratni o‘tkazish talabi"],"a":0,"e":"Rejalashtirish turli rejalarning tuzilishi, ta’lim maqsadi, didaktik tamoyillar va faoliyatni tashkil etish vositalari haqidagi bilimga tayanadi."},
{"m":1617,"c":"KS.01","l":"oquv-jarayonini-rejalashtirish","k":"bilish","d":1,"s":"Fanlararo kompetensiyalarni dars mazmuniga oldindan singdirish qaysi kasbiy kompetensiya sohasiga kiradi?","o":["O‘quv jarayonini rejalashtirish","Ta’lim samaradorligini ta’minlash","O‘zlashtirishni baholash va qayta aloqa","Tarbiyaviy faoliyatni tashkil etish"],"a":0,"e":"Fanlararo bog‘lanish va kompetensiyalar qaysi mavzu, vazifa va faoliyat orqali shakllanishi darsdan oldin rejalashtiriladi; shu sabab u KS.01ga kiradi."},
{"m":1618,"c":"KS.01","l":"oquv-jarayonini-rejalashtirish","k":"bilish","d":1,"s":"Dars maqsadi, shakli, usuli va vaqt taqsimotini oldindan belgilash qaysi mehnat vazifasiga tegishli?","o":["O‘quv jarayonini rejalashtirish","O‘quv jarayonini bevosita boshqarish","O‘quv natijalarini yakuniy baholash","O‘quv jarayonini retrospektiv tahlil qilish"],"a":0,"e":"Maqsad, shakl, metod va vaqtni dars boshlanishidan oldin belgilash rejalashtirishning to‘g‘ridan-to‘g‘ri mazmunidir."},
{"m":1619,"c":"KS.01","l":"oquv-jarayonini-rejalashtirish","k":"bilish","d":2,"s":"O‘quv dasturini moslashtirish zarurati eng avvalo qaysi dalil bilan asoslanadi?","o":["Direktorning og‘zaki istagi bilan","Yig‘ilishdagi norasmiy taklif bilan","O‘quvchi ehtiyoj va qiziqishlari bilan","Bir martalik past baho natijasi bilan"],"a":2,"e":"Dastur doirasidagi moslashtirish o‘quvchilarning aniqlangan ta’limiy ehtiyoji, qiziqishi va tayyorgarligiga tayanishi kerak; u o‘zboshimcha qaror bo‘lmasligi lozim."},
{"m":1644,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"bilish","d":2,"s":"Qaysi harakat ta’lim samaradorligini ta’minlashdagi bevosita mehnat vazifasiga kiradi?","o":["Erishiladigan vazifa va mos materialni belgilash","Kasbiy rivojlanish rejasini yillik tuzish","Ota-onalar bilan hamkorlik shartini imzolash","Maktab mulki xavfsizligini inventarizatsiya qilish"],"a":0,"e":"Erishiladigan vazifalarni belgilash, mavzuga mos material tanlash va dars vaqtidan oqilona foydalanish ta’lim samaradorligini bevosita ta’minlaydi."},
{"m":1645,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"qollash","d":2,"s":"Pedagog dars vaqtini boshqardi, AKTdan foydalandi va mustaqil ishni maqsadga mos tanladi. Qaysi soha ko‘nikmalari namoyon?","o":["O‘quv jarayonini rejalashtirish","Tarbiyaviy faoliyatni tashkil etish","Hamkorlikni yo‘lga qo‘yish","Ta’lim samaradorligini ta’minlash"],"a":3,"e":"Vaqtni oqilona boshqarish, AKTni pedagogik maqsadda qo‘llash va mustaqil ishni tanlash KS.02ning zarur ko‘nikmalaridir."},
{"m":1646,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"bilish","d":2,"s":"Turli ehtiyojli va iqtidorli o‘quvchilar bilan samarali ishlash uchun pedagog qaysi bilimlar majmuiga tayanadi?","o":["Differensial va inklyuziv yondashuvlar bilimiga","Faqat sinf jurnalini yuritish qoidalariga","Binodan foydalanish texnik me’yorlariga","Yakuniy attestatsiya jadvali tartibiga"],"a":0,"e":"Turli ta’limiy ehtiyojlarni qondirish uchun differensiallashtirish, inklyuzivlik va iqtidorli o‘quvchilar bilan ishlash xususiyatlarini bilish zarur."},
{"m":1647,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"qollash","d":3,"s":"Pedagog baholash dalillaridan foydalanib usulini tahlil qildi va o‘quvchi maqsadiga mos yangi yondashuv tanladi. Qaysi kompetensiya sohasi ustuvor?","o":["Ta’lim samaradorligini ta’minlash","Kasbiy rivojlanishni hujjatlashtirish","Tarbiyaviy tadbirni tashkil etish","Ota-onalar bilan hamkorlik qilish"],"a":0,"e":"Dalil asosida yondashuv samaradorligini tahlil qilish va o‘qitish usulini o‘quvchi maqsadiga moslashtirish KS.02 doirasidagi mehnat harakatidir."},
{"m":1648,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"qollash","d":2,"s":"O‘qituvchi o‘quvchilarning darsdan tashqari qiziqishlarini bilib, misol va vazifalarni shu qiziqishlarga bog‘ladi. Qaysi usul qo‘llandi?","o":["Turli texnologiyani navbatsiz qo‘llash","Shaxsiy qiziqish orqali motivatsiyalash","Motivatsiyani faqat yakunda tahlil qilish","Vaqtni qisqartirish orqali faollashtirish"],"a":1,"e":"O‘quvchining shaxsiy qiziqishini dars mazmuni bilan bog‘lash ichki motivatsiyani kuchaytiradi va faol ishtirokni rag‘batlantiradi."},
{"m":1650,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"qollash","d":2,"s":"O‘qituvchi 4K yondashuvi orqali o‘quvchilarning turli yo‘nalishda fikrlashi va hamkorligini faollashtirdi. Qaysi harakat bajarildi?","o":["Jamoaviy ishni nazoratsiz qoldirish","Ko‘rgazmalarni ketma-ket namoyish etish","O‘qitishning faol usullaridan foydalanish","Vazifalarni faqat yodlashga yo‘naltirish"],"a":2,"e":"4K kommunikatsiya, kollaboratsiya, kreativlik va kritik fikrlashni faol topshiriqlar orqali rivojlantiradi; bu faol o‘qitish usullariga kiradi."},
{"m":1655,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"qollash","d":3,"s":"4K modelidan foydalanish natijasida o‘quvchilar erkin fikr bildirdi, muammoni yakka va jamoada hal qildi. Qaysi ko‘nikma rivojlantirildi?","o":["Fan mazmunini tayyor shaklda takrorlash","Interaktiv vositani maqsadsiz qo‘llash","Asosiy kompetensiya va hayotiy ko‘nikmalar","Faqat loyiha hujjatlarini rasmiylashtirish"],"a":2,"e":"Erkin fikr, muammo yechish, hamkorlik va tanqidiy yondashuv o‘quvchilarning asosiy kompetensiyalari hamda hayotiy ko‘nikmalarini rivojlantiradi."},
{"m":1680,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"bilish","d":2,"s":"Qaysi harakat baholash va qayta aloqa sohasidagi mehnat vazifasiga kiradi?","o":["Darsdan tashqari to‘garak jadvalini tuzish","Ota-onalar yig‘ilishi vaqtini belgilash","Sinf bezagini o‘quvchilar bilan tanlash","Natijani tahlil qilib davomiy o‘qishga undash"],"a":3,"e":"O‘quvchi yutug‘ini baholash, natijani asoslash va undan keyingi o‘qishga motivatsiya yaratish KS.03dagi asosiy mehnat vazifalaridan biridir."},
{"m":1681,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"bilish","d":2,"s":"Baholash sohasidagi zarur ko‘nikmani aniqlang.","o":["Natijani turli vositalarda baholash","Maktab tadbirini tashkiliy boshqarish","Fanlararo mavzuni rejalarga taqsimlash","Sinfda xavfsizlik yo‘riqnomasini o‘tkazish"],"a":0,"e":"Turli maqsad va o‘quvchi ehtiyojiga mos baholash vositalarini tanlash, qo‘llash va natijani sharhlash KS.03ning zarur ko‘nikmasidir."},
{"m":1682,"c":"KS.03","l":"ozlashtirishni-baholash-va-qayta-aloqa","k":"bilish","d":2,"s":"Baholash sohasida pedagog bilishi lozim bo‘lgan nazariy asos qaysi?","o":["Test blankini chop etish texnik tartibi","Bahoni elektron jurnalga kiritish amaliy usuli","Dars xonasini jihozlash bo‘yicha me’yorlar","Baholash nazariyalari va test tuzish qoidalari"],"a":3,"e":"Pedagog zamonaviy baholash nazariyalari, usullar, ularning o‘quvchiga ta’siri va turli ehtiyojga mos diagnostik topshiriq tuzish qoidalarini bilishi kerak."},
{"m":1725,"c":"KS.04","l":"tarbiyaviy-faoliyatni-tashkil-etish","k":"bilish","d":2,"s":"Qaysi harakat tarbiyaviy faoliyatni tashkil etishdagi mehnat vazifasiga kiradi?","o":["Faqat yakuniy test variantini tuzish","Darslik boblarini haftalarga taqsimlash","O‘quvchilar o‘zini o‘zi boshqarishini qo‘llab-quvvatlash","Fan bo‘yicha diagnostik ballni hisoblash"],"a":2,"e":"O‘quvchilarning o‘zini o‘zi boshqarish organlarini tashkil etish va qo‘llab-quvvatlash mas’uliyat, tashabbus hamda fuqarolik pozitsiyasini tarbiyalaydi."},
{"m":1726,"c":"KS.04","l":"tarbiyaviy-faoliyatni-tashkil-etish","k":"bilish","d":2,"s":"Tarbiyaviy faoliyat uchun zarur ko‘nikmani aniqlang.","o":["O‘quvchini tenglik va hurmatli munosabatga yo‘naltirish","Nazorat savollarini murakkablik bo‘yicha kodlash","O‘quv yuklamasini sinflar bo‘yicha taqsimlash","Dars natijasini statistik jadvalda hisoblash"],"a":0,"e":"Tenglik, adolat va hurmatga asoslangan munosabatni rivojlantirish tarbiyaviy faoliyatning bevosita ko‘nikmasidir."},
{"m":1727,"c":"KS.04","l":"tarbiyaviy-faoliyatni-tashkil-etish","k":"bilish","d":2,"s":"Tarbiyaviy faoliyatni asosli tashkil etish uchun qaysi bilimlar majmui zarur?","o":["Yosh pedagogikasi, psixologiya va bola huquqlari","Fan bo‘yicha murakkab nazariy formulalar majmui","Maktab mulkini saqlash texnik qoidalari","Choraklik bahoni hisoblash algoritmlari va jadvallari"],"a":0,"e":"Tarbiyaviy ish o‘quvchi yoshi va psixologiyasi, tarbiya metodikasi, bola huquqlari hamda ta’lim qonunchiligi haqidagi bilimlarga tayanadi."},
{"m":1731,"c":"KS.04","l":"tarbiyaviy-faoliyatni-tashkil-etish","k":"qollash","d":2,"s":"O‘quvchilar ustoz bilan urush faxriysini bayram bilan tabriklab, xotira va qadrlash tadbirini o‘tkazdi. Qaysi kompetensiya sohasi namoyon?","o":["O‘quv jarayonini rejalashtirish","Ta’lim samaradorligini ta’minlash","Tarbiyaviy faoliyat sohasi","Hamkasblar bilan hamkorlik"],"a":2,"e":"Tarixiy xotira, hurmat va vatanparvarlik qadriyatlarini amaliy tadbir orqali shakllantirish tarbiyaviy faoliyat sohasiga kiradi."},
{"m":2723,"c":"KS.07","l":"hamkasblar-va-ota-onalar-bilan-hamkorlik","k":"qollash","d":2,"s":"O‘qituvchi muayyan o‘quvchining qiyinchiligi haqida shu sinfda dars beradigan hamkasblari bilan maslahatlashdi. Qaysi soha namoyon?","o":["O‘quv jarayonini rejalashtirish","Ta’lim samaradorligini ta’minlash","Tarbiyaviy faoliyatni tashkil etish","Hamkasblar bilan hamkorlik"],"a":3,"e":"O‘quvchi muammosini birgalikda tushunish va yechim topish uchun hamkasblar bilan maslahatlashish KS.07 doirasidagi hamkorlik harakatidir."},
{"m":2717,"c":"KS.02","l":"talim-samaradorligini-taminlash","k":"qollash","d":2,"s":"O‘qituvchi guruhli topshiriqlar orqali o‘quvchilarning fikr almashishi va o‘zaro yordam berishini rivojlantirdi. Qaysi mehnat harakati bajarildi?","o":["Faol metodni qisqa namoyish qilish","Hayotiy ko‘nikmani alohida tushuntirish","Jamoaviy va loyihaviy ishni tashkil etish","Metakognitiv nazorat varag‘ini yakka to‘ldirish"],"a":2,"e":"Guruhli topshiriqda umumiy maqsad, rol va o‘zaro yordamni tashkil etish o‘quvchilarning jamoaviy ishini boshqarish mehnat harakatidir."},
{"m":2738,"c":"KS.04","l":"tarbiyaviy-faoliyatni-tashkil-etish","k":"qollash","d":2,"s":"Pedagog taraqqiyot, yoshlar imkoniyatlari va jamiyatdagi qarorlar mohiyatini muhokama qilib, o‘quvchilarda faol fuqarolik pozitsiyasini rivojlantirdi. Qaysi harakat bajarildi?","o":["Sinfdan tashqari vaqtni ko‘ngilochar tashkil etish","Nizoni faqat suhbat orqali to‘xtatish","Ko‘p madaniyatli muhitni nazariy tushuntirish","Fuqarolik pozitsiyasi va tashabbuskorlikni rivojlantirish"],"a":3,"e":"Jamiyat taraqqiyoti va fuqaroning mas’uliyati haqidagi asosli muhokama o‘quvchilarning fuqarolik pozitsiyasi va tashabbuskorligini rivojlantiradi."},
{"m":1393,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"bilish","d":2,"s":"Fan, texnologiya, muhandislik, san’at va matematikani integratsiyalovchi STEAM yondashuvi qaysi ta’lim paradigmasiga yaqin?","o":["An’anaviy reproduktiv paradigma","Bixevioristik nazorat paradigmasi","Insonparvarlik muloqot paradigmasi","Ilmiy-texnik integrativ paradigma"],"a":3,"e":"STEAM ilmiy bilim va texnologiyani muhandislik, san’at hamda matematika bilan integratsiyalab, amaliy muammo yechishga yo‘naltiradi."},
{"m":1491,"c":"KS.05","l":"xavfsiz-rivojlantiruvchi-talim-muhiti","k":"qollash","d":2,"s":"Sinf soatida internetdagi axborot xurujlari, zararli ta’sir va ijtimoiy tarmoqlardan mas’uliyatli foydalanish muhokama qilindi. Asosiy tarbiyaviy maqsad qaysi?","o":["Raqamli muhitda xavfsiz va tanqidiy xulqni shakllantirish","Internetdagi barcha materialni ishonchli deb qabul qildirish","Ijtimoiy tarmoqlardan foydalanishni to‘liq taqiqlash","O‘quvchini faqat texnik atamalarni yodlashga yo‘naltirish"],"a":0,"e":"Axborot xuruji mavzusi o‘quvchida raqamli xavfsizlik, manbani tanqidiy baholash va onlayn muhitda mas’uliyatli xulqni shakllantirishi kerak."},
{"m":1492,"c":"PM.GEN.08","l":"talim-texnologiyalari-va-vaziyatga-mos-tanlov","k":"qollash","d":2,"s":"Guruhlar alohida muammolar ustida birga ishlab, yechimlarni muhokama qildi va eng maqbul variantni tanladi. Qaysi yondashuv ustuvor?","o":["Individual diskussiya","Ta’limiy raqobat","Hamkorlikda o‘qitish","Erkin aqliy hujum"],"a":2,"e":"Umumiy vazifa, o‘zaro yordam, fikr almashish va birgalikda qaror qabul qilish hamkorlikda o‘qitishning asosiy belgilaridir."},
{"m":3100,"c":"PM.GEN.01","l":"pedagogika-didaktika-tarbiya-va-yosh-psixologiyasi","k":"bilish","d":1,"s":"Pedagogika fanining predmeti va yo‘nalishini qaysi ta’rif to‘liqroq ifodalaydi?","o":["Ta’lim mazmuni va metodlarini o‘rganuvchi xususiy fan","Ta’lim-tarbiya mohiyati va qonuniyatlarini o‘rganuvchi ijtimoiy fan","Tarbiya usullarini tavsiflaydigan yordamchi gumanitar fan","Ta’lim nazariyasini takrorlaydigan amaliy fan"],"a":1,"e":"Pedagogika ta’lim va tarbiya jarayonining mohiyati, mazmuni, qonuniyatlari, tamoyillari, shakl va metodlarini o‘rganuvchi ijtimoiy fandir."}
] $bank$::jsonb) source(v);
DO $task530_b10$
DECLARE b task530_batch10%rowtype;actor uuid;subject_id uuid;construct_id uuid;lesson_id uuid;question_id uuid;option_id uuid;option_ids uuid[];i int;n int;bad int;bad_id uuid;bad_code text;bad_source text;
BEGIN
IF (SELECT count(*) FROM task530_batch10)<>30 THEN RAISE EXCEPTION 'TASK530_B10_COUNT';END IF;
IF EXISTS(SELECT 1 FROM task530_batch10 t JOIN public.questions q ON q.source_reference='telegram:@PedMahoratGuli:'||t.message_id OR q.source_reference LIKE 'telegram:@PedMahoratGuli:'||t.message_id||'|%') THEN RAISE EXCEPTION 'TASK530_B10_SOURCE_ALREADY_REPRESENTED';END IF;
SELECT id INTO STRICT actor FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false);IF (SELECT count(*) FROM public.profiles WHERE role='admin' AND NOT coalesce(is_blocked,false))<>1 THEN RAISE EXCEPTION 'TASK530_B10_OWNER_NOT_UNIQUE';END IF;SELECT id INTO STRICT subject_id FROM public.subjects WHERE code='informatika';CREATE TEMP TABLE task530_b10_ids(id uuid PRIMARY KEY) ON COMMIT DROP;
FOR b IN SELECT * FROM task530_batch10 ORDER BY message_id LOOP SELECT c.id,l.id INTO STRICT construct_id,lesson_id FROM public.constructs c JOIN public.lesson_constructs lc ON lc.construct_id=c.id JOIN public.lessons l ON l.id=lc.lesson_id WHERE c.code=b.construct_code AND c.is_active AND l.slug=b.lesson_slug AND l.status='published';IF EXISTS(SELECT 1 FROM public.questions q WHERE q.status IN('review','published') AND regexp_replace(lower(btrim(q.stem_md)),'[^[:alnum:]]+','','g')=regexp_replace(lower(btrim(b.stem_md)),'[^[:alnum:]]+','','g')) THEN RAISE EXCEPTION 'TASK530_B10_ACTIVE_EXACT_DUPLICATE_%',b.message_id;END IF;question_id:=gen_random_uuid();INSERT INTO public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,author_id,is_generated,source_lesson_id,source_reference) VALUES(question_id,subject_id,construct_id,CASE WHEN b.construct_code LIKE 'KS.%' THEN 'KS' ELSE 'PM.GEN' END,'Y1',b.cognitive,b.difficulty,b.stem_md,'review',NULL,true,lesson_id,b.source_reference);INSERT INTO task530_b10_ids VALUES(question_id);option_ids:=ARRAY[]::uuid[];FOR i IN 0..3 LOOP option_id:=gen_random_uuid();option_ids:=array_append(option_ids,option_id);INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(option_id,question_id,'a',i,b.options->>i);END LOOP;INSERT INTO public.question_keys(question_id,payload,explanation_md) VALUES(question_id,jsonb_build_object('correct_option_id',option_ids[b.correct_index+1]),b.explanation_md);END LOOP;
WITH x AS(SELECT q.id,count(o.id) oc,count(DISTINCT lower(btrim(o.content_md))) dc,count(*)FILTER(WHERE o.id::text=k.payload->>'correct_option_id') kc,min(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) mi,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1)) ma,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1))FILTER(WHERE o.id::text=k.payload->>'correct_option_id') cw,max(array_length(regexp_split_to_array(btrim(o.content_md),'[[:space:]]+'),1))FILTER(WHERE o.id::text<>k.payload->>'correct_option_id') mw FROM task530_b10_ids r JOIN public.questions q ON q.id=r.id JOIN public.question_options o ON o.question_id=q.id AND btrim(o.side)='a' JOIN public.question_keys k ON k.question_id=q.id GROUP BY q.id)SELECT count(*)FILTER(WHERE oc<>4 OR dc<>4 OR kc<>1 OR mi<1 OR ma>mi*1.8 OR cw>mw*1.25),count(*)INTO bad,n FROM x;IF bad<>0 OR n<>30 THEN RAISE EXCEPTION 'TASK530_B10_BALANCE_%_COUNT_%',bad,n;END IF;
INSERT INTO public.pedagogy_owner_release_waivers(question_id,authorized_by,content_fingerprint,authority,provenance)SELECT q.id,actor,public.professional_question_fingerprint(q.id),'owner_explicit_no_external_expert_20261018','TASK-530 batch 10; owner-delegated AI expert rewrite of PedMahoratGuli professional-standard items; key independently checked; independent human expert signoff NOT claimed' FROM task530_b10_ids r JOIN public.questions q ON q.id=r.id;GET DIAGNOSTICS n=ROW_COUNT;IF n<>30 THEN RAISE EXCEPTION 'TASK530_B10_WAIVERS_%',n;END IF;
SELECT r.id,q.source_reference,s.finding_code INTO bad_id,bad_source,bad_code FROM task530_b10_ids r JOIN public.questions q ON q.id=r.id CROSS JOIN LATERAL public.pedagogy_semantic_quality_signals(r.id)s WHERE s.severity='high' ORDER BY r.id,s.finding_code LIMIT 1;IF bad_id IS NOT NULL THEN RAISE EXCEPTION 'TASK530_B10_SEMANTIC_%_%',bad_source,bad_code;END IF;
UPDATE public.questions q SET status='published',updated_at=now() FROM task530_b10_ids r WHERE q.id=r.id AND q.status='review';GET DIAGNOSTICS n=ROW_COUNT;IF n<>30 THEN RAISE EXCEPTION 'TASK530_B10_PUBLISHED_%',n;END IF;SELECT count(*) INTO n FROM task530_b10_ids r JOIN public.questions q ON q.id=r.id JOIN public.pedagogy_owner_release_waivers w ON w.question_id=q.id JOIN public.pedagogy_published_revisions p ON p.question_id=q.id WHERE q.status='published' AND w.content_fingerprint=public.professional_question_fingerprint(q.id);IF n<>30 THEN RAISE EXCEPTION 'TASK530_B10_POSTFLIGHT_%_OF_30',n;END IF;
END $task530_b10$;COMMIT;
